create or replace function sispro_private.collection_mechanic(k text) returns text language sql immutable set search_path='' as $$ select case k when 'processos' then 'processos' when 'prazos' then 'prazos' when 'agenda' then 'agenda' when 'autosMetadata' then 'autos' when 'etiquetasCatalogo' then 'processos' when 'etiquetasVinculos' then 'processos' else null end $$;
create or replace function public.sispro_read_workspace() returns jsonb language plpgsql security definer set search_path='' as $$ declare d jsonb; rev bigint; begin if auth.uid() is null or not sispro_private.is_active() or coalesce(auth.jwt()->>'is_anonymous','false')='true' then raise exception 'Access denied' using errcode='42501'; end if; select data,revision into d,rev from public.sispro_workspaces where user_id=auth.uid(); return jsonb_build_object('revision',rev,'data',coalesce((select jsonb_object_agg(key,value) from jsonb_each(coalesce(d,'{}'::jsonb)) where sispro_private.is_ceo() or sispro_private.mechanic_level(sispro_private.collection_mechanic(key))>=1),'{}'::jsonb),'levels',(select coalesce(jsonb_object_agg(id,sispro_private.mechanic_level(id)),'{}'::jsonb) from public.sispro_mechanics)); end $$;
create or replace function public.sispro_write_workspace(expected_revision bigint, changes jsonb) returns bigint language plpgsql security definer set search_path='' as $$ declare d jsonb; rev bigint; k text; v jsonb; begin if auth.uid() is null or not sispro_private.is_active() or coalesce(auth.jwt()->>'is_anonymous','false')='true' then raise exception 'Access denied' using errcode='42501'; end if; if changes is null or jsonb_typeof(changes)<>'object' then raise exception 'Invalid changes'; end if; for k,v in select key,value from jsonb_each(changes) loop if jsonb_typeof(v)<>'object' or (not sispro_private.is_ceo() and sispro_private.mechanic_level(sispro_private.collection_mechanic(k))<2) then raise exception 'Access denied' using errcode='42501'; end if; end loop; perform pg_advisory_xact_lock(hashtextextended(auth.uid()::text,0)); select data,revision into d,rev from public.sispro_workspaces where user_id=auth.uid() for update; if rev is distinct from expected_revision then raise exception 'Revision conflict' using errcode='40001'; end if; if rev is null then insert into public.sispro_workspaces(user_id,data,revision) values(auth.uid(),changes,1); return 1; end if; update public.sispro_workspaces set data=d||changes,revision=rev+1 where user_id=auth.uid(); return rev+1; end $$;
revoke all on function public.sispro_read_workspace(),public.sispro_write_workspace(bigint,jsonb) from public,anon;
grant execute on function public.sispro_read_workspace(),public.sispro_write_workspace(bigint,jsonb) to authenticated;
revoke select,insert,update,delete on public.sispro_workspaces from authenticated,anon;